        end_time_formatted: "2026-09-25 23:59",
        detail: "Americana duo Chatham Rabbits pull from their distinctive North Carolina musical influences to create a bright alternative sound filled with nods to old time and string band music. This is an extraordinary band to see live for all fans of Americana and regional roots music.\n\n\n\nChatham Rabbits is Sarah and Austin McCombie. They live on a farm in NC that has been in Sarah’s family since 1753.\nChatham Rabbits headlined at The Kennedy Center’s Millennium Stage. \nAre passionate about “making sure you leave our concerts feeling better than when you arrived.”",
