        detail: "Come out and see us on September 19th and 26th for the best Oktoberfest party in the area. We’re the only German owned brewery in the area. Authentic Oktoberfest beer, authentic music from Oktoberfest, German food, and games. We are tapping a cask of our Oktoberfest at 3pm to officially kick off the party, but the drinking and food start at noon. If you want to try the cask make sure you’re here around 3 because it goes fast. Games start at 5pm. Make sure you purchase our locally handmade Oktoberfest stein while supplies last. Great beer, crowds, food, and cocktails. There will be a best dressed completion so wear your best Dirndl and Lederhosen and a stein hoist completion for the ladies, and for the men.",
