        detail: "Ben Colvin Quartet + Special Guest Thu, Oct 01 Ben Colvin Quartet brings a dynamic mix of groove-based music to the stage ranging from 60s era soul jazz, to Afro Cuban rhythms, to contemporary fusion and funk. Led by longtime Asheville saxophonist Ben Colvin, the group features Joe Enright (drums), Danny Iannucci (bass), Alex Taub (keys), and a Special Guest. Their sets move from the timeless compositions of Wayne Shorter and Hank Mobley to the more modern sounds of Roy Hargrove and Ben Wendel, along with a selection of originals. Expect an evening of swinging horns, deep grooves and spirited improvisation. \n \n Reserve your preferred table in advance. $10/door \n 07:00 PM SHOW 08:30 PM SHOW",
