        name: `Alan Hall\'s Xploritoreum | ft. Christian Howes, Dr. Bill Bares, Shannon Hoover & Tim Fischer`,
        sort_time: "2026-10-10 20:00:00",
        end_time_formatted: "2026-10-10 23:59",
        detail: "Alan Hall\'s Xploritoreum | ft. Christian Howes, Dr. Bill Bares, Shannon Hoover & Tim Fischer Sat, Oct 10 Founded in 2025 by drummer, composer Alan Hall, Xploritoreum is an energetic, modern instrumental group hailing from Asheville, North Carolina. Hall’s musical touchstones include latin grooves, jazz and funk rhythmic traditions; pop song structures; improvisation; and blues harmonies. \n \n About Alan Hall’s composing: \n “Hall’s strikingly melodic original compositions…..build off spirited rhythms or paint effectively moody landscapes. Binding everything together is the singable quality of Hall’s writing.” - Andrew Gilbert \n \n \"…a delight for younger, open-eared listeners that don\'t mind having the door to something new opened for them.” -Mid-west Records \n \n Alan Hall will be joined by a stellar crew including Bill Bares (piano), Christian Howes (violin), Tim Fischer-(guitar) and Shannon Hoover (bass). \n 08:00 PM SHOW 09:30 PM SHOW",
        location: "Hotel Eve 56 N Lexington Ave, Asheville, NC 28801",
