        end_time_formatted: "2026-10-14 23:59",
        detail: "The Queen Sessions | Kellin Watson Wed, Oct 14 The Queen Sessions at Hotel Eve | A celebration of the legendary women who shaped jazz. \n \n Hotel Eve proudly presents The Queen Sessions , a concert series curated by Melissa McKinney, honoring the iconic voices that defined generations of jazz. \n \n Each Wednesday evening features a rotating lineup of Asheville\'s premier vocalists, each bringing their own style, artistry, and interpretation to the music of legends like Ella Fitzgerald, Billie Holiday, Nina Simone, Sarah Vaughan, Dinah Washington, Abbey Lincoln, and more. \n \n No two performances are alike. Every week offers a fresh cast of artists & new collaborations. \n \n Reserve your seats here ~ capacity is limited. \n \n Curated by Melissa McKinney. \n \n 07:00 PM SHOW 08:30 PM SHOW",
