        detail: "The Steve LaSpina Quintet | Ft: Justin Ray, Peter Dimery, Tim Fischer, Alan Hall Thu, Oct 15 Celebrated bassist and composer Steve LaSpina has been a vital force on the New York and international jazz scene for more than four decades. A longtime collaborator with jazz icons including Stan Getz, Benny Carter, Phil Woods, Joe Williams, Clark Terry, Chet Baker, Randy Brecker, Pat Martino, and Jim Hall, LaSpina has appeared on more than 275 recordings as both a leader and sideman. His work as a bandleader and decades of international touring reflect a distinctive playing style grounded in deep musicality, nuance, and integrity. \n \n For this special performance, LaSpina leads a quartet featuring Justin Ray on trumpet, Peter Dimery on tenor saxophone, Tim Fisher on Guitar and Alan Hall on drums. A show not to miss! \n \n Advance reservations recommended. $10/Door. \n 07:00 PM SHOW 08:30 PM SHOW",
