        detail: "Grant Green Tribute featuring Adam Knight Quintet Sat, Oct 24 \n Guitarist Adam Knight leads a stellar quintet in tribute to Grant Green, one of jazz guitar’s most soulful and distinctive voices. Often overshadowed in his time by Wes Montgomery and George Benson, Green created an unmistakable blues-driven sound that moved effortlessly through hard bop, soul jazz, funk, R&B, and Latin jazz. \n \n Knight is a dynamic guitarist, composer, and Applied Lecturer in Jazz Guitar at the University of South Carolina and Clemson University. He has toured and recorded extensively, opening for artists including Maceo Parker, Incubus, and Robert Randolph, and performs throughout the Southeast with his own jazz projects and the Greenville Jazz Collective Big Band. \n \n Expect an evening that digs beyond the familiar, bringing some of Grant Green’s lesser-known music to life alongside the soulful grooves that made his playing so singular. \n \n Featuring: \n Adam Knight — guitar \n Shannon Hoover — bass \n Keith Davis — keys \n Tim Blackwell — drums \n Jeff Holland — percussion \n \n Advance Tickets are recommended. \n Read More 08:00 PM SHOW 09:30 PM SHOW",
